B.Z_=new A.fH("Lettres de gratitude","Chaque membre \xe9crit une lettre de remerciement \xe0 un autre membre de la famille.","\u2709\ufe0f","30 min","social",B.a4e)
B.a5W=s(["Choisir Maghrib (id\xe9ale)","Faire les ablutions ensemble","Le papa dirige la pri\xe8re","Faire des douas ensemble apr\xe8s"],t.s)
B.Z4=new A.fH("Pri\xe8re en jama\xe2 \xe0 la maison","Organisez une pri\xe8re en groupe \xe0 la maison avec toute la famille.","\ud83d\udd4c","15 min","spirituel",B.a5W)
