B.LJ=new A.e1("coran","Lecture du Coran","Quran Recitation","\ud83d\udcd6",15,null,null)
B.Lw=new A.e1("dhikr_matin","Adhk\xe2r du matin","Morning Adhkar","\ud83c\udf05",10,null,null)
B.LA=new A.e1("dhikr_soir","Adhk\xe2r du soir","Evening Adhkar","\ud83c\udf07",10,null,null)
B.LD=new A.e1("istighfar","Istighf\xe2r (100x)","Istighfar (100x)","\ud83e\udd32",10,"Le Proph\xe8te \ufdfa demandait pardon \xe0 Allah plus de 100 fois par jour","The Prophet \ufdfa asked forgiveness from Allah more than 100 times daily")
B.Lz=new A.e1("salawat","Sal\xe2t 'ala Nabi \ufdfa","Salah upon the Prophet \ufdfa","\ud83d\udc9a",10,"Envoyer les salutations sur le Proph\xe8te \ufdfa","Send blessings upon the Prophet \ufdfa")
B.a9V=s([B.LJ,B.Lw,B.LA,B.LD,B.Lz],t.bC)
