B.Lu=new A.e1("sadaqa","Sadaqa (aum\xf4ne)","Sadaqa (charity)","\ud83d\udcb0",15,"M\xeame un sourire est une sadaqa","Even a smile is sadaqa")
B.LL=new A.e1("parents","Bienfaisance envers les parents","Kindness to parents","\ud83d\udc68\u200d\ud83d\udc69\u200d\ud83d\udc67",15,null,null)
