B.VX=new A.d9("\u0627\u064e\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650 \u0627\u0644\u064e\u0651\u0630\u0650\u064a \u0623\u064e\u062d\u0652\u064a\u064e\u0627\u0646\u064e\u0627 \u0628\u064e\u0639\u0652\u062f\u064e \u0645\u064e\u0627 \u0623\u064e\u0645\u064e\u0627\u062a\u064e\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0646\u064f\u0651\u0634\u064f\u0648\u0631\u064f","Al-hamdu lillahi alladhi ahyana ba'da ma amatana wa ilayhi an-nusur","Louange \xe0 Allah qui nous a ramen\xe9s \xe0 la vie apr\xe8s nous avoir fait mourir, et vers Lui sera notre retour","Praise be to Allah who gave us life after He had caused us to die, and unto Him is the resurrection","Quran 2:179",1)
B.VT=new A.d9("\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u0652\u0646\u064e\u0627 \u0648\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064e \u0627\u0644\u0652\u0645\u064f\u0644\u0652\u0643\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650 \u0631\u064e\u0628\u0650\u0651 \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e","Asbahna wa asbaha al-mulku lillahi rabbi al-'alamin","Nous sommes arriv\xe9s au matin et la royaut\xe9 appartient \xe0 Allah, le Seigneur de l'univers","We have reached the morning and all sovereignty belongs to Allah, Lord of the worlds","Tirmidhi 3488",1)
B.W_=new A.d9("\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0628\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u0628\u064e\u062d\u0652\u0646\u064e\u0627 \u0648\u064e\u0628\u0650\u0643\u064e \u0623\u064e\u0645\u0652\u0633\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0628\u0650\u0643\u064e \u0646\u064e\u062d\u0652\u064a\u064e\u0627 \u0648\u064e\u0628\u0650\u0643\u064e \u0646\u064e\u0645\u064f\u0648\u062a\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0646\u064f\u0651\u0634\u064f\u0648\u0631\u064f","Allahumma bika asbahna wa bika amsayna wa bika nahya wa bika namut wa ilayika an-nusur","\xd4 Allah ! C'est par Toi que nous arrivons au matin et au soir, c'est par Toi que nous vivons et mourons, et vers Toi est notre r\xe9surrection","O Allah! By You we reach the morning and the evening, by You we live and die, and to You is the resurrection","Tirmidhi 3391",1)
B.vS=new A.d9("\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0643\u064e \u0627\u0644\u0652\u0639\u064e\u0641\u0652\u0648\u064e \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0627\u0641\u0650\u064a\u064e\u0629\u064e \u0641\u0650\u064a \u0627\u0644\u062f\u064f\u0651\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650","Allahumma inni as'aluka al-'afw wa al-'afiya fi ad-dunya wa al-akhira","\xd4 Allah ! Je Te demande le pardon et le bien-\xeatre en ce monde et dans l'au-del\xe0","O Allah! I ask You for pardon and well-being in this world and in the hereafter","Ibn Majah 3892",1)
B.vO=new A.d9("\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0625\u0650\u0646\u0650\u0651\u064a \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064f\u0641\u0652\u0631\u0650 \u0648\u064e\u0627\u0644\u0652\u0641\u064e\u0642\u0652\u0631\u0650 \u0648\u064e\u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0639\u064e\u0630\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0642\u064e\u0628\u0652\u0631\u0650","Allahumma inni a'udhu bika min al-kufr wa al-faqr wa a'udhu bika min 'adhab al-qabr","\xd4 Allah ! Je cherche refuge aupr\xe8s de Toi contre la m\xe9cr\xe9ance et la pauvret\xe9, et je cherche refuge aupr\xe8s de Toi contre le ch\xe2timent de la tombe","O Allah! I seek refuge in You from disbelief and poverty, and I seek refuge in You from the punishment of the grave","Abu Dawud 5090",1)
B.vM=new A.d9("\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0628\u0650\u062d\u064e\u0645\u0652\u062f\u0650\u0647\u0650 \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650","Subhana llahi wa bihamdihi subhana llahi al-'azim","Gloire \xe0 Allah et louange \xe0 Lui, gloire \xe0 Allah le Puissant","Glory be to Allah and praise be to Him, glory be to Allah the Magnificent","Muslim 2694",100)
B.vP=new A.d9(u.cu,"Subhana llahi wa bihamdihi 'adada khalqihi wa rida nafsihi wa zinata 'arshihi wa midat kalimatihi","Gloire \xe0 Allah et louange \xe0 Lui, autant que le nombre de Ses cr\xe9ations, la satisfaction de Lui-m\xeame, le poids de Son Tr\xf4ne et l'encre de Ses paroles",u.u,"Muslim 2726",1)
B.vN=new A.d9(u.b,u.v,u.I,u.o,"Bukhari 3293",10)
B.vU=new A.d9(u.aY,u.F,u.L,u.bG,"Quran 112:1-4",3)
B.vQ=new A.d9(u.aT,u.m,u.X,u.Q,"Quran 113:1-5",3)
B.vR=new A.d9(u.cS,u.O,u.x,u.cZ,"Quran 114:1-6",3)
B.vT=new A.d9("\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0628\u0650\u0633\u0652\u0645\u064f\u0643\u064e \u0623\u064e\u0645\u064f\u0648\u062a\u064f \u0648\u064e\u0623\u064e\u062d\u0652\u064a\u064e\u0627","Allahumma bismuka amutu wa ahya","\xd4 Allah ! Au nom de Ton nom, je meurs et je vis","O Allah! In Your name I die and I live","Bukhari 6314",1)
B.vL=new A.d9("\u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0627\u0644\u062a\u064e\u0651\u0627\u0645\u064e\u0651\u0629\u0650 \u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0650\u0651 \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e","A'udhu bi kalimat illahi at-tammah min sharri ma khalaq","Je cherche refuge dans les paroles compl\xe8tes d'Allah contre le mal de ce qu'Il a cr\xe9\xe9","I seek refuge in the perfect words of Allah from the evil of what He has created","Muslim 2708",3)
B.oG=new A.d9("\u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0623\u064e\u0646\u0652\u062a\u064e \u0627\u0644\u0633\u064e\u0651\u0644\u064e\u0627\u0645\u064f \u0648\u064e\u0645\u0650\u0646\u0652\u0643\u064e \u0627\u0644\u0633\u064e\u0651\u0644\u064e\u0627\u0645\u064f \u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u0652\u062a\u064e \u064a\u064e\u0627 \u0630\u064e\u0627 \u0627\u0644\u0652\u062c\u064e\u0644\u064e\u0627\u0644\u0650 \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u0643\u0652\u0631\u064e\u0627\u0645\u0650","Allahumma anta as-salam wa minka as-salam tabarakta ya dha al-jalal wa al-ikram","\xd4 Allah ! Tu es la Paix et la Paix vient de Toi. B\xe9ni sois-Tu, \xd4 Seigneur de majest\xe9 et d'honneur","O Allah! You are Peace and from You comes Peace. Blessed are You, O Lord of Majesty and Honor","Muslim 834",1)
