B.aEr=new A.i9(1,"Intention (Niyyah)","Intention (Niyyah)","Formuler mentalement l'intention de faire l'ablution pour purifier son corps avant la pri\xe8re. L'intention n'est pas prononc\xe9e \xe0 voix haute.","Form the intention in your heart to perform wudu to purify your body before prayer. The intention is not pronounced aloud.","\ud83e\udd32",null,null,null,null,0)
B.aEl=new A.i9(2,"Bismillah","Bismillah","Commencer par prononcer le nom d'Allah avant de se laver.","Begin by pronouncing the name of Allah before washing.","\ud83d\udde3\ufe0f","\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650","Bismillah","Au nom d'Allah","In the name of Allah",0)
B.aEh=new A.i9(3,"Mains","Hands","Laver les deux mains jusqu'aux poignets en veillant \xe0 frotter entre les doigts.","Wash both hands up to the wrists, making sure to rub between the fingers.","\ud83d\udc50",null,null,null,null,3)
B.aEn=new A.i9(4,"Bouche (Madmada)","Mouth (Madmada)","Prendre de l'eau dans la bouche, la faire tourner, puis la recracher.","Take water in your mouth, swish it around, then spit it out.","\ud83d\udca7",null,null,null,null,3)
B.aEi=new A.i9(5,"Nez (Istinshaq)","Nose (Istinshaq)","Aspirer de l'eau dans le nez avec la main droite, puis se moucher avec la gauche.","Inhale water into your nose with your right hand, then blow it out with your left.","\ud83d\udc43",null,null,null,null,3)
B.aEo=new A.i9(6,"Visage","Face","Laver tout le visage de la ligne des cheveux au menton, et d'une oreille \xe0 l'autre.","Wash the entire face from the hairline to the chin, and from ear to ear.","\ud83d\ude0c",null,null,null,null,3)
B.aEq=new A.i9(7,"Bras droit","Right arm","Laver le bras droit depuis les doigts jusqu'au coude inclus.","Wash the right arm from the fingers to the elbow, inclusive.","\ud83d\udcaa",null,null,null,null,3)
B.aEp=new A.i9(8,"Bras gauche","Left arm","Laver le bras gauche depuis les doigts jusqu'au coude inclus.","Wash the left arm from the fingers to the elbow, inclusive.","\ud83d\udcaa",null,null,null,null,3)
B.aEm=new A.i9(9,"T\xeate (Masah)","Head (Masah)","Passer les mains humides sur toute la t\xeate depuis le front jusqu'\xe0 la nuque, une seule fois.","Wipe your wet hands over the entire head from the forehead to the back of the neck, one time.","\ud83e\udd1a",null,null,null,null,1)
B.aEj=new A.i9(10,"Oreilles","Ears","Passer les pouces humides derri\xe8re les oreilles et les index dans les oreilles, en m\xeame temps que le masah de la t\xeate.","Wipe the insides and backs of your ears with your wet fingers and thumbs at the same time as wiping your head.","\ud83d\udc42",null,null,null,null,1)
B.aEg=new A.i9(11,"Pied droit puis gauche","Right foot then left","Laver chaque pied jusqu'\xe0 la cheville en frottant entre les orteils. Commencer par le pied droit.","Wash each foot up to the ankle, rubbing between the toes. Start with the right foot.","\ud83e\uddb6",null,null,null,null,3)
B.aEk=new A.i9(12,"Dua de fin","Closing supplication","Apr\xe8s le wudu, lever les yeux vers le ciel et r\xe9citer cette invocation.","After wudu, look up to the sky and recite this supplication.","\ud83e\udd32","\u0623\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0623\u064e\u0646\u0652 \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u064e\u0651\u0627 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u062d\u0652\u062f\u064e\u0647\u064f \u0644\u064e\u0627 \u0634\u064e\u0631\u0650\u064a\u0643\u064e \u0644\u064e\u0647\u064f\u060c \u0648\u064e\u0623\u064e\u0634\u0652\u0647\u064e\u062f\u064f \u0623\u064e\u0646\u064e\u0651 \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064b\u0627 \u0639\u064e\u0628\u0652\u062f\u064f\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f","Ash-hadu an l\xe2 il\xe2ha illall\xe2hu wahdahu l\xe2 shar\xeeka lah, wa ash-hadu anna Muhammadan 'abduhu wa ras\xfbluh","Je t\xe9moigne qu'il n'y a de divinit\xe9 qu'Allah, Seul et sans associ\xe9, et que Muhammad est Son serviteur et Messager.","I testify that there is no deity except Allah alone, without partner, and I testify that Muhammad is His servant and Messenger.",0)
